13	// parseOrgRole maps the --role flag for `entire grant org add` to the
14	// generated enum, rejecting unknown values at the CLI boundary so the
15	// user gets a clear message instead of a server 422. Mirrors
16	// parseProjectOwnerType. The empty string means "use the server default
17	// (member)" and is the caller's signal to omit the field entirely; it is
18	// not handled here.
19	func parseOrgRole(s string) (coreapi.AddOrgMemberInputBodyRole, error) {
20		switch s {
21		case "owner":
22			return coreapi.AddOrgMemberInputBodyRoleOwner, nil
23		case "admin":
24			return coreapi.AddOrgMemberInputBodyRoleAdmin, nil
25		case "member":
26			return coreapi.AddOrgMemberInputBodyRoleMember, nil
27		default:
28			return "", fmt.Errorf("invalid --role %q: must be \"owner\", \"admin\", or \"member\"", s)
29		}
30	}
31	
32	// validateGrantRole rejects unknown project/repo grant roles at the CLI
33	// boundary (reader, writer, admin) so the user gets a clear message instead of
34	// a server 422. The GrantProjectAccess and GrantRepoAccess input bodies use
35	// distinct enum types that share these values, so callers cast the validated
36	// string to whichever type they need.
37	func validateGrantRole(role string) error {
38		switch role {
39		case "reader", "writer", "admin":
40			return nil
41		default:
42			return fmt.Errorf("invalid --role %q: must be \"reader\", \"writer\", or \"admin\"", role)
43		}
44	}
45	
46	// validateGrantGranteeType rejects grantee kinds the control plane no longer
47	// accepts when granting. A grant resolves to an account (from the provider
48	// identity), so "account" is the only valid kind ("" means the default,
49	// account). org/team granting was dropped server-side (COR-561) and the
50	// generated client enum is account-only, so catch it here with a clear message
51	// instead of an opaque enum-encoding error.
52	func validateGrantGranteeType(granteeType string) error {
53		switch granteeType {
54		case "", "account":
55			return nil
56		default:
57			return fmt.Errorf("invalid --grantee-type %q: only \"account\" is supported", granteeType)
58		}
59	}
