327	// granteeMode names the two ways `grant project remove` / `grant repo remove`
328	// can address a grantee.
329	type granteeMode int
330	
331	const (
332		granteeModeProvider granteeMode = iota // --provider + --provider-user-id
333		granteeModeID                          // --grantee-type + --grantee-id
334	)
335	
336	// parseGranteeMode validates that exactly one addressing mode was supplied
337	// and fully specified, returning which one. The two modes are mutually
338	// exclusive: a provider account (github + user id) hits the by-provider revoke
339	// route, while a ULID grantee hits the typed-id route that also covers org and
340	// team grantees.
341	func parseGranteeMode(provider, providerUserID, granteeType, granteeID string) (granteeMode, error) {
342		byProvider := provider != "" || providerUserID != ""
343		byID := granteeType != "" || granteeID != ""
344		switch {
345		case byProvider && byID:
346			return 0, errors.New("specify either --provider/--provider-user-id or --grantee-type/--grantee-id, not both")
347		case byProvider:
348			if provider == "" || providerUserID == "" {
349				return 0, errors.New("both --provider and --provider-user-id are required")
350			}
351			return granteeModeProvider, nil
352		case byID:
353			if granteeType == "" || granteeID == "" {
354				return 0, errors.New("both --grantee-type and --grantee-id are required")
355			}
356			return granteeModeID, nil
357		default:
358			return 0, errors.New("identify the grantee with --provider/--provider-user-id or --grantee-type/--grantee-id")
359		}
360	}
