492	// bindGranteeFlags wires the shared --provider / --provider-user-id pair
493	// that identifies a grantee across the org/project/repo add+remove verbs,
494	// marking both required.
495	func bindGranteeFlags(cmd *cobra.Command, provider, providerUserID *string) {
496		cmd.Flags().StringVar(provider, "provider", "", "identity provider (e.g. github) (required)")
497		cmd.Flags().StringVar(providerUserID, "provider-user-id", "", "provider-specific user id (required)")
498		markRequired(cmd, "provider", "provider-user-id")
499	}
