501	// revokeGrant runs a grant-removal API call idempotently. A 404 means the
502	// grantee already has no such grant — the desired end state — so it's reported
503	// as a no-op rather than surfaced as a raw error, matching runControlPlaneDelete.
504	// verb is the success word ("Revoked"/"Removed"); subject describes the grant,
505	// e.g. "github/12345 from repo acme".
506	func revokeGrant(cmd *cobra.Command, verb, subject string, revoke func() error) error {
507		if err := revoke(); err != nil {
508			if isCoreNotFound(err) {
509				cmd.Printf("%s: no such grant; nothing to revoke\n", subject)
510				return nil
511			}
512			return err
513		}
514		cmd.Printf("%s %s\n", verb, subject)
515		return nil
516	}
