15	// newRepoCmd is the hidden `entire repo` command group: control-plane
16	// repository lifecycle (create, list within a project, get, delete) on the
17	// Entire control plane. Git content operations (clone, log, diff, …) are
18	// intentionally out of scope here. Surfaced via `entire labs`.
19	func newRepoCmd() *cobra.Command {
20		cmd := &cobra.Command{
21			Use:    "repo",
22			Short:  "Manage Entire repositories",
23			Hidden: true,
24		}
25		addControlPlaneFlags(cmd)
26		cmd.AddCommand(newRepoCreateCmd())
27		cmd.AddCommand(newRepoListCmd())
28		cmd.AddCommand(newRepoGetCmd())
29		cmd.AddCommand(newRepoDeleteCmd())
30		cmd.AddCommand(newRepoMirrorCmd())
31		return cmd
