13	// Control-plane commands reference orgs and projects by their parent ULID in
14	// many places (repo create --project, project create --owner, grant org/project
15	// <id>, …). ULIDs are unfriendly to type, so these refs also accept a human
16	// name: looksLikeULID decides which form was given, and the resolveXRef helpers
17	// turn a name into its ULID. A ULID is always passed straight through with no
18	// network call. A name is resolved by the control plane's O(1), case-insensitive
19	// by-name lookup (the server matches on lower(name) and returns the single match
20	// under the response's singular `org`/`project` field, or 404) — the CLI never
21	// lists everything and filters client-side.
22	
23	// looksLikeULID reports whether s has the shape of a ULID: 26 characters drawn
24	// from Crockford base32 (digits plus uppercase letters, excluding I, L, O, U).
25	// The check is shape-only and case-insensitive on the alphabet; it never hits
26	// the network. A name that happened to be 26 valid base32 characters would be
27	// misread as an id, but real org/project names don't take that form, and the
28	// user can always fall back to the explicit ULID.
29	func looksLikeULID(s string) bool {
30		if len(s) != 26 {
31			return false
32		}
33		for _, r := range strings.ToUpper(s) {
34			switch {
35			case r >= '0' && r <= '9':
36			case r >= 'A' && r <= 'Z' && r != 'I' && r != 'L' && r != 'O' && r != 'U':
37			default:
38				return false
39			}
40		}
41		return true
42	}
