137	// name-filtered query returns the single match (or none) under `repos`.
138	func resolveRepoRef(ctx context.Context, c *coreapi.Client, ref, projectRef string) (string, error) {
139		if looksLikeULID(ref) {
140			return ref, nil
141		}
142		if projectRef == "" {
143			return "", fmt.Errorf("repo %q is a name; pass --project <name|ULID> to resolve it, or use a repo ULID", ref)
