25	// resolveTestClient builds a coreapi client pointed at a test server whose
26	// handler is h, and returns the client plus a counter of HTTP requests seen.
27	// It lets the resolver tests assert the load-bearing invariant from
28	// resolveref.go's doc comment: a ULID ref makes zero network calls, a name ref
29	// makes exactly one.
30	func resolveTestClient(t *testing.T, h http.HandlerFunc) (*coreapi.Client, *atomic.Int64) {
31		t.Helper()
32		var calls atomic.Int64
33		srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
34			calls.Add(1)
35			w.Header().Set("Content-Type", "application/json")
36			h(w, r)
37		}))
38		t.Cleanup(srv.Close)
39		c, err := coreapi.NewWithBearer(srv.URL, "tok")
40		if err != nil {
41			t.Fatalf("NewWithBearer: %v", err)
42		}
43		return c, &calls
44	}
